    "title": "동기 — 군산의 임피역",
    "content": "교과서 134쪽 「스스로 활동」 — 임피역은 일제가 군산선 철도를 놓으며 지은 작은 역이에요. 호남평야에서 거둔 쌀을 군산항으로 모아 일본으로 보내기 쉬웠어요. 「일제가 임피역을 지은 까닭」을 써 보게 하세요. 철도는 식민 통치 이전부터 놓이기 시작했고, 땅을 강제로 거두고 사람들을 동원해 놓았음을 함께 짚어요(지도서 292·298쪽).",
